@tool
extends Node

func run() -> String:
	var d := DirAccess.open("E:/")
	var moved: Array = []
	var mk := d.make_dir_recursive("ghost-company-quarantine/broken-gltf")
	var pairs := [
		["ghost-company-main/assets/gltf/Decals/Decal_Line_90.gltf", "ghost-company-quarantine/broken-gltf/Decal_Line_90.gltf"],
		["ghost-company-main/assets/gltf/Decals/Decal_Line_90.gltf.import", "ghost-company-quarantine/broken-gltf/Decal_Line_90.gltf.import"]
	]
	for p in pairs:
		var err := d.rename(String(p[0]), String(p[1]))
		moved.append(String(p[0]) + " -> " + str(err))
	# confirm __MACOSX gone
	var mac := d.dir_exists("ghost-company-main/__MACOSX")
	var decal := FileAccess.file_exists("res://assets/gltf/Decals/Decal_Line_90.gltf")
	var round := FileAccess.file_exists("res://assets/gltf/Decals/Decal_Line_90_Round.gltf")
	return "MACOSX_exists=" + str(mac) + " decal_moved=" + str(decal == false) + " round_intact=" + str(round) + " | " + str(moved)
